        (4000, 'certified mail', 'I sent it by certified mail.')
    ) AS expected(id, expression_text, sentence_text)
    LEFT JOIN writing_expression we ON we.id = expected.id
    WHERE we.id IS NULL
       OR we.target_expression_text IS DISTINCT FROM expected.expression_text
       OR we.representative_sentence_text IS DISTINCT FROM expected.sentence_text;

    IF mismatched > 0 THEN
        RAISE EXCEPTION 'LAN-568 pronunciation assets: % writing_expression rows are missing or differ from the texts the audio was generated from (first id %). The expression migration must insert insert_writing_expression_1000.sql in file order from id 3001.',
            mismatched, first_mismatch;
    END IF;
END
$$;

ON CONFLICT (writing_expression_id, accent_locale) DO UPDATE SET
    expression_audio_url = EXCLUDED.expression_audio_url,
    sentence_audio_url = EXCLUDED.sentence_audio_url,
    words = EXCLUDED.words,
    updated_at = now();

DO $$
BEGIN
    IF (SELECT count(*) FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 3001 AND 4000) <> 3000 THEN
        RAISE EXCEPTION 'LAN-568 pronunciation assets: expected 3000 rows for 3001~4000';
    END IF;

    IF EXISTS (
        SELECT 1 FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 3001 AND 4000
        GROUP BY accent_locale
        HAVING count(*) <> 1000
    ) OR (SELECT count(DISTINCT accent_locale) FROM expression_pronunciation_asset
          WHERE writing_expression_id BETWEEN 3001 AND 4000) <> 3 THEN
        RAISE EXCEPTION 'LAN-568 pronunciation assets: every accent locale must have 1000 rows';
    END IF;

    IF EXISTS (
        SELECT 1 FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 3001 AND 4000
          AND (sentence_audio_url IS NULL
               OR sentence_audio_url NOT LIKE 'https://d19azau1un4t7r.cloudfront.net/content/expression-pronunciation-audio/' || writing_expression_id || '/' || accent_locale || '/sentence/%')
    ) THEN
        RAISE EXCEPTION 'LAN-568 pronunciation assets: sentence audio URL is missing or points to another expression';
    END IF;

    IF (SELECT count(*) FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 3001 AND 4000
          AND expression_audio_url IS NULL) <> 75 THEN
        RAISE EXCEPTION 'LAN-568 pronunciation assets: expected 75 templated expressions without expression audio';
    END IF;

    IF EXISTS (
        SELECT 1 FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 3001 AND 4000
          AND expression_audio_url IS NOT NULL
          AND expression_audio_url NOT LIKE 'https://d19azau1un4t7r.cloudfront.net/content/expression-pronunciation-audio/' || writing_expression_id || '/' || accent_locale || '/expression/%'
    ) THEN
        RAISE EXCEPTION 'LAN-568 pronunciation assets: expression audio URL points to another expression';
    END IF;

    -- V126 이후 단어 음성은 전부 (억양, 해시) 공용 주소여야 한다. V126의 검사는 한 번만 돌므로
    -- 이 배치가 옛 형식(표현id/억양/word/순서)이나 다른 억양의 주소를 들고 오면 여기서 막는다.
    IF EXISTS (
        SELECT 1
        FROM expression_pronunciation_asset asset
        CROSS JOIN LATERAL jsonb_array_elements(asset.words) AS word
        WHERE asset.writing_expression_id BETWEEN 3001 AND 4000
          AND (word ->> 'audioUrl') !~ ('^https://d19azau1un4t7r\.cloudfront\.net/content/expression\-pronunciation\-audio/word/' || asset.accent_locale || '/[0-9a-f]{64}\.mp3$')
    ) THEN
        RAISE EXCEPTION 'LAN-568 pronunciation assets: every word audio URL must be the shared word/{accent}/{hash}.mp3 address of the row accent';
    END IF;
END
$$;
